export default function ProductEditForm({
  product,
}: {
  product: {
    id: number;
    name: string;
    price: number;
    description: string;
    image: string;
    createdAt: Date;
    updatedAt: Date;
  } | null;
}) {
  const router = useRouter();

  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const form = useForm<CreateProductBodyType>({
    resolver: zodResolver(CreateProductBody),
    defaultValues: {
      name: "",
      description: "",
      price: 0,
      image: "",
    },
  });

  async function onSubmit(values: CreateProductBodyType) {
    if (loading) return;
    setLoading(true);
    try {
      const formData = new FormData();
      if (file) {
        formData.append("file", file);
        const uploadResult = await productApi.uploadImage(formData);
        const imageUrl = uploadResult.payload.data;
        values.image = imageUrl;
      }
      const result = await productApi.create(values);

      toast.success(result.payload.message || "Create product successfully");

      router.push("/products");
    } catch (error: any) {
      handleErrorApi({ errors: error, setError: form.setError });
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="w-full">
      <Form {...form}>
        <form
          onSubmit={form.handleSubmit(onSubmit, (error) => {
            console.log(error);
          })}
          className="space-y-4 max-w-[500px] mx-auto"
          noValidate
        >
          <FormField
            control={form.control}
            name="name"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Tên</FormLabel>
                <FormControl>
                  <Input placeholder="Type name" type="text" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="price"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Price</FormLabel>
                <FormControl>
                  <Input
                    placeholder="Type price"
                    type="number"
                    onChange={(e) => field.onChange(Number(e.target.value))}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="description"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Description</FormLabel>
                <FormControl>
                  <Textarea placeholder="Type description" {...field} />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="image"
            render={({ field }) => (
              <FormItem>
                <FormLabel>Image</FormLabel>
                <FormControl>
                  <Input
                    type="file"
                    accept="image/*"
                    onClick={() => {
                      setFile(null);
                      form.setValue("image", "");
                    }}
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) {
                        setFile(file);
                        field.onChange("http://localhost:3000/" + file.name);
                        const value = form.getValues("image");
                        console.log(value);
                      }
                    }}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          {file && (
            <div>
              <Image src={URL.createObjectURL(file)} alt="Preview" width={200} height={200} />
              <Button
                className="mt-2"
                variant={"destructive"}
                onClick={() => {
                  setFile(null);
                  form.setValue("image", "");
                }}
                type="button"
              >
                Xóa hình ảnh
              </Button>
            </div>
          )}

          <Button type="submit" className="mt-4 w-full">
            Thêm sản phẩm
          </Button>
        </form>
      </Form>
    </div>
  );
}
